-- EST-13: the versions a match decision is recorded against (BUS-15) move with what the evaluation reads, and with
-- nothing else. The search's stage is no longer counted: no match is evaluated on it and it does not close a search
-- (EST-09). The criteria of a commercial search now are, and so are a commercial listing's premium, floor area and
-- property type (BUS-12). Additive: the two triggers of 0037 are replaced by their new version, with the same body;
-- no table, column or row is written when this is applied.
DROP TRIGGER applicants_match_inputs;
CREATE TRIGGER applicants_match_inputs AFTER UPDATE OF requirement_priorities,household_children,household_children_status,move_in_date,lease_term_months,near,requirements,operation,budget_min,budget_max,budget_stretch,property_types,bedrooms_min,bedrooms_max,bedrooms_ideal,bathrooms_min,parking_spaces,outdoor,furnished,pets,parishes_wanted,parishes_excluded,housing_status,buyer_position,archived_at,search_state,search_category,search_operation,commercial_kind,commercial_use,area_min,area_max,area_unit,commercial_purchase,commercial_rent,commercial_rent_period,commercial_premium,commercial_expenses ON applicants
WHEN OLD.requirement_priorities IS NOT NEW.requirement_priorities OR OLD.household_children IS NOT NEW.household_children OR OLD.household_children_status IS NOT NEW.household_children_status OR OLD.move_in_date IS NOT NEW.move_in_date OR OLD.lease_term_months IS NOT NEW.lease_term_months OR OLD.near IS NOT NEW.near OR OLD.requirements IS NOT NEW.requirements OR OLD.operation IS NOT NEW.operation OR OLD.budget_min IS NOT NEW.budget_min OR OLD.budget_max IS NOT NEW.budget_max OR OLD.budget_stretch IS NOT NEW.budget_stretch OR OLD.property_types IS NOT NEW.property_types OR OLD.bedrooms_min IS NOT NEW.bedrooms_min OR OLD.bedrooms_max IS NOT NEW.bedrooms_max OR OLD.bedrooms_ideal IS NOT NEW.bedrooms_ideal OR OLD.bathrooms_min IS NOT NEW.bathrooms_min OR OLD.parking_spaces IS NOT NEW.parking_spaces OR OLD.outdoor IS NOT NEW.outdoor OR OLD.furnished IS NOT NEW.furnished OR OLD.pets IS NOT NEW.pets OR OLD.parishes_wanted IS NOT NEW.parishes_wanted OR OLD.parishes_excluded IS NOT NEW.parishes_excluded OR OLD.housing_status IS NOT NEW.housing_status OR OLD.buyer_position IS NOT NEW.buyer_position OR OLD.archived_at IS NOT NEW.archived_at OR OLD.search_state IS NOT NEW.search_state OR OLD.search_category IS NOT NEW.search_category
 OR OLD.search_operation IS NOT NEW.search_operation OR OLD.commercial_kind IS NOT NEW.commercial_kind OR OLD.commercial_use IS NOT NEW.commercial_use OR OLD.area_min IS NOT NEW.area_min OR OLD.area_max IS NOT NEW.area_max OR OLD.area_unit IS NOT NEW.area_unit OR OLD.commercial_purchase IS NOT NEW.commercial_purchase OR OLD.commercial_rent IS NOT NEW.commercial_rent OR OLD.commercial_rent_period IS NOT NEW.commercial_rent_period OR OLD.commercial_premium IS NOT NEW.commercial_premium OR OLD.commercial_expenses IS NOT NEW.commercial_expenses BEGIN
 UPDATE applicants SET matches_revision=matches_revision+1, match_inputs_revision=match_inputs_revision+1,
 match_ranking_version=0 WHERE id=NEW.id;
END;
-- Premium, floor area and property type are read for commercial listings only: on a home they change no evaluation.
DROP TRIGGER listings_match_inputs;
CREATE TRIGGER listings_match_inputs AFTER UPDATE OF operation,availability,archived_at,bedrooms,bathrooms,parish,published,sale_price,rent,rent_period,feat_pets,feat_parking,feat_furnished,feat_outdoor,feat_type,feat_evidence,tenure_type,housing_category,restriction,matchable,use,country,currency,premium,interior_area_sqft,property_type ON listings
WHEN OLD.operation IS NOT NEW.operation OR OLD.availability IS NOT NEW.availability OR OLD.archived_at IS NOT NEW.archived_at OR OLD.bedrooms IS NOT NEW.bedrooms OR OLD.bathrooms IS NOT NEW.bathrooms OR OLD.parish IS NOT NEW.parish OR OLD.published IS NOT NEW.published OR OLD.sale_price IS NOT NEW.sale_price OR OLD.rent IS NOT NEW.rent OR OLD.rent_period IS NOT NEW.rent_period OR OLD.feat_pets IS NOT NEW.feat_pets OR OLD.feat_parking IS NOT NEW.feat_parking OR OLD.feat_furnished IS NOT NEW.feat_furnished OR OLD.feat_outdoor IS NOT NEW.feat_outdoor OR OLD.feat_type IS NOT NEW.feat_type OR OLD.feat_evidence IS NOT NEW.feat_evidence OR OLD.tenure_type IS NOT NEW.tenure_type OR OLD.housing_category IS NOT NEW.housing_category OR OLD.restriction IS NOT NEW.restriction OR OLD.matchable IS NOT NEW.matchable OR OLD.use IS NOT NEW.use OR OLD.country IS NOT NEW.country OR OLD.currency IS NOT NEW.currency
 OR (NEW.use='commercial' AND (OLD.premium IS NOT NEW.premium OR OLD.interior_area_sqft IS NOT NEW.interior_area_sqft OR OLD.property_type IS NOT NEW.property_type)) BEGIN
 INSERT INTO listing_match_inputs(listing_id,version) VALUES(NEW.id,1)
 ON CONFLICT(listing_id) DO UPDATE SET version=version+1;
 UPDATE applicants SET matches_revision=matches_revision+1 WHERE id IN (SELECT applicant_id FROM matches WHERE listing_id=NEW.id);
END;
